import os
import re
import subprocess
import psutil
import time


class EmssFileLogger(object):
    def __init__(self, emss_host='10.0.1.1', emss_port='7001'):
        self.emss_host = emss_host
        self.emss_port = emss_port
        self.proc = None
        self.filepath = None

        try:
            self._debug_om = int(os.environ['DEBUG_OM'])
        except Exception:
            self._debug_om = 0

    def start_emss_logging(self):
        if self.filepath is None:
            self._debug('Filepath should be set for emss logger. Logging to default ta_emss.log')
            self.filepath = './ta_emss.log'

        cmd = self._get_logging_cmd()
        self._add_log_header()
        self.proc = self._start_process(cmd)

        self._debug('start_emss_logging: cmd=%s, proc=%s' % (cmd, self.proc))
        if self.proc:
            self._debug('start_emss_logging: pid=%s' % self.proc.pid)

    def stop_emss_logging(self):
        if self.proc:
            self._debug('stop_emss_logging - killing parent process %s and its children' % self.proc.pid)
            self._kill_process_and_children(self.proc.pid)
            self.proc = None

        self.filepath = None

    def _add_log_header(self):
        try:
            prefix = "\n\n" if os.path.exists(self.filepath) else ""
            header = prefix + time.strftime("%Y-%d-%m %H:%M:%S", time.localtime()) + (" |##:LOG:## %s:%s\n\n" % (self.emss_host, self.emss_port))
            with open(self.filepath, "a") as logfile:
                logfile.write(header)
        except Exception as exc:
            self._debug('Cannot write header to log file: %s: %s' % (self.filepath, exc))

    def _start_process(self, cmd):
        proc = None
        try:
            proc = subprocess.Popen(cmd, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
            time.sleep(1)  # Wait to setup a pipe
        except Exception as exc:
            self._debug('Failure %s in starting emss logger process for %s %s, with %s' % (
                str(exc), self.emss_host, self.emss_port, cmd)
            )
        return proc

    def _kill_process_and_children(self, proc_pid):
        try:
            time.sleep(1)  # Empty buffers before killing
            parent = psutil.Process(proc_pid)
            to_terminate = parent.children(recursive=True)
            to_terminate.append(parent)
            for proc in to_terminate:
                self._debug('[{}] Logging terminating: {}'.format(proc_pid, proc.pid))
                # proc.terminate()
                proc.kill()
            self._debug('[{}] Logging waiting for termination'.format(proc_pid))
            gone, still_alive = psutil.wait_procs(to_terminate, timeout=10, callback=None)
            for proc in still_alive:
                self._debug('[{}] Killing still alive: {}'.format(proc_pid, proc.pid))
                proc.kill()
            self._debug('[{}] Logging terminated'.format(proc_pid))
        except Exception as exc:
            self._debug('[{}] Cannot kill logging parent/child: {}'.format(proc_pid, str(exc)))

    def _get_logging_cmd(self):
        nc_cmd = 'netcat %s %s' % (self.emss_host, self.emss_port)
        cmd = "%s >> '%s'" % (nc_cmd, self.filepath)
        return cmd

    def _get_logging_name(self, filename):
        # remove all non-word characters (everything except numbers and letters)
        # replace all whitespace with underscore
        filename = re.sub(r"[^\w\s]", '', filename)
        filename = re.sub(r"\s+", '_', filename)

        return '%s_%s_%s_%s' % ('emss', self.emss_host, self.emss_port, filename)

    def set_filepath(self, dir_path, filename):
        dir_path_with_emss = os.path.join(dir_path, 'emss')
        if not os.path.exists(dir_path_with_emss):
            os.makedirs(dir_path_with_emss)
        self.filepath = os.path.join(dir_path_with_emss, self._get_logging_name(filename) + '.log')

    def _debug(self, msg, level=0):
        if self._debug_om > level:
            self._print(msg)

    def _print(self, msg):
        ts = time.strftime("[%d.%m.%y %H:%M:%S]", time.localtime())
        print("%s [EMSS LOGGER][%s]: %s" % (ts, '%s_%s' % (self.emss_host, self.emss_port), str(msg)))


def get_robot_output_dir():
    logging_dir = None
    try:
        from robot.libraries.BuiltIn import BuiltIn
        logging_dir = BuiltIn().get_variable_value('${OUTPUT_DIR}')
    except Exception:
        logging_dir = None
    return logging_dir


if __name__ == '__main__':
    print('Test')
    a = EmssFileLogger()

    try:
        print('Start logging')
        a.set_filepath('.', 'emss')
        a.start_emss_logging()
        print('Sleep')
        time.sleep(10)
    except Exception as exc:
        print('Something went wrong %s' % str(exc))
    finally:
        print('Stop')
        a.stop_emss_logging()
